+const fs = require('node:fs');
+const path = require('node:path');
+
+const root = process.cwd();
+
+function parseCsv(filename) {
+  const text = fs.readFileSync(path.join(root, filename), 'utf8').trimEnd();
+  const lines = text.split(/\r?\n/);
+  function splitCsvLine(line) {
+    const fields = [];
+    let field = '';
+    let quoted = false;
+    for (let i = 0; i < line.length; i += 1) {
+      const char = line[i];
+      if (char === '"') {
+        if (quoted && line[i + 1] === '"') {
+          field += '"';
+          i += 1;
+        } else {
+          quoted = !quoted;
+        }
+      } else if (char === ',' && !quoted) {
+        fields.push(field);
+        field = '';
+      } else {
+        field += char;
+      }
+    }
+    if (quoted) throw new Error(`Unclosed CSV quote in ${filename}`);
+    fields.push(field);
+    return fields;
+  }
+  const headers = splitCsvLine(lines[0]);
+  return lines.slice(1).filter(Boolean).map((line, index) => {
+    const values = splitCsvLine(line);
+    if (values.length !== headers.length) {
+      throw new Error(`CSV field count mismatch in ${filename}:${index + 2}`);
+    }
+    return Object.fromEntries(headers.map((header, i) => [header, values[i]]));
+  });
+}
+
+const orders = parseCsv('orders.csv').map(row => ({ ...row, amount: Number(row.amount) }));
+const paymentRows = parseCsv('payments.csv').map(row => ({ ...row, amount: Number(row.amount) }));
+const refunds = parseCsv('refunds.csv').map(row => ({ ...row, amount: Number(row.amount) }));
+const orderById = new Map(orders.map(order => [order.order_id, order]));
+
+const paymentsById = new Map();
+const duplicatePaymentIds = [];
+for (const payment of paymentRows) {
+  const previous = paymentsById.get(payment.payment_id);
+  if (previous) {
+    if (JSON.stringify(previous) !== JSON.stringify(payment)) {
+      throw new Error(`Conflicting duplicate payment ID ${payment.payment_id}`);
+    }
+    if (!duplicatePaymentIds.includes(payment.payment_id)) duplicatePaymentIds.push(payment.payment_id);
+  } else {
+    paymentsById.set(payment.payment_id, payment);
+  }
+}
+
+const uniquePayments = [...paymentsById.values()];
+const validPayments = uniquePayments.filter(p => p.status === 'paid' && orderById.has(p.order_id));
+const failedPaymentIds = uniquePayments.filter(p => p.status === 'failed').map(p => p.payment_id);
+const cancelledPaymentIds = uniquePayments.filter(p => p.status === 'cancelled').map(p => p.payment_id);
+const orphanPaymentIds = uniquePayments
+  .filter(p => p.status === 'paid' && !orderById.has(p.order_id))
+  .map(p => p.payment_id);
+
+const validPaymentById = new Map(validPayments.map(p => [p.payment_id, p]));
+const appliedRefunds = [];
+const pendingRefundIds = [];
+const orphanRefundIds = [];
+for (const refund of refunds) {
+  const payment = validPaymentById.get(refund.payment_id);
+  const status = refund.refund_id === 'R303' ? 'settled' : refund.status;
+  if (refund.status === 'pending' && refund.refund_id !== 'R303') pendingRefundIds.push(refund.refund_id);
+  if (status === 'settled' && payment && payment.order_id === refund.order_id) {
+    appliedRefunds.push(refund);
+  } else if (status === 'settled') {
+    orphanRefundIds.push(refund.refund_id);
+  }
+}
+
+const paidByOrder = new Map(orders.map(order => [order.order_id, 0]));
+for (const payment of validPayments) {
+  paidByOrder.set(payment.order_id, paidByOrder.get(payment.order_id) + payment.amount);
+}
+const refundedByOrder = new Map(orders.map(order => [order.order_id, 0]));
+for (const refund of appliedRefunds) {
+  refundedByOrder.set(refund.order_id, refundedByOrder.get(refund.order_id) + refund.amount);
+}
+const orderResults = orders.map(order => {
+  const validPayment = paidByOrder.get(order.order_id);
+  const appliedRefund = refundedByOrder.get(order.order_id);
+  return {
+    order_id: order.order_id,
+    order_amount: order.amount,
+    valid_payment: validPayment,
+    applied_refund: appliedRefund,
+    net_received: validPayment - appliedRefund,
+    unpaid_before_refunds: Math.max(order.amount - validPayment, 0),
+  };
+});
+
+const total = field => orderResults.reduce((sum, row) => sum + row[field], 0);
+const result = {
+  source_files: ['orders.csv', 'payments.csv', 'refunds.csv', 'rules.md'],
+  orders: {
+    count: orders.length,
+    total_amount: total('order_amount'),
+  },
+  payments: {
+    duplicate_ids: duplicatePaymentIds,
+    valid_payment_ids: validPayments.map(p => p.payment_id),
+    valid_payment_total: total('valid_payment'),
+    failed_ids: failedPaymentIds,
+    cancelled_ids: cancelledPaymentIds,
+    orphan_paid_ids: orphanPaymentIds,
+  },
+  refunds: {
+    applied_refund_ids: appliedRefunds.map(r => r.refund_id),
+    applied_refund_total: total('applied_refund'),
+    source_pending_not_applied_ids: pendingRefundIds,
+    orphan_settled_ids: orphanRefundIds,
+  },
+  totals: {
+    applied_refund: total('applied_refund'),
+    net_received: total('net_received'),
+    unpaid_before_refunds: total('unpaid_before_refunds'),
+  },
+  per_order: orderResults,
+  correction_applied: {
+    refund_id: 'R303',
+    source_status: 'pending',
+    effective_status: 'settled',
+    basis: 'CORRECTION-ORCHID (parent event-4): “最终计算必须按这条用户更正把 R303 作为已结算退款处理。”',
+  },
+};
+
+if (result.totals.applied_refund !== 60 || result.totals.net_received !== 415 ||
+    result.totals.unpaid_before_refunds !== 225 || result.payments.valid_payment_total !== 475) {
+  throw new Error(`Unexpected reconciliation totals: ${JSON.stringify(result.totals)}`);
+}
+console.log(JSON.stringify(result, null, 2));
*** End Patch"}

