+const fs = require('node:fs');
+
+function readCsv(path) {
+  const [headerLine, ...lines] = fs.readFileSync(path, 'utf8').trim().split(/\r?\n/);
+  const headers = headerLine.split(',');
+  return lines.filter(Boolean).map((line) => {
+    const values = line.split(',');
+    return Object.fromEntries(headers.map((header, i) => [header, values[i]]));
+  });
+}
+
+const orders = readCsv('orders.csv').map((r) => ({ ...r, amount: Number(r.amount) }));
+const orderById = new Map(orders.map((r) => [r.order_id, r]));
+const paymentRows = readCsv('payments.csv').map((r) => ({ ...r, amount: Number(r.amount) }));
+const firstPaymentById = new Map();
+const duplicatePaymentIds = [];
+for (const payment of paymentRows) {
+  if (firstPaymentById.has(payment.payment_id)) {
+    duplicatePaymentIds.push(payment.payment_id);
+    if (JSON.stringify(firstPaymentById.get(payment.payment_id)) !== JSON.stringify(payment)) {
+      throw new Error(`Conflicting duplicate payment ${payment.payment_id}`);
+    }
+  } else {
+    firstPaymentById.set(payment.payment_id, payment);
+  }
+}
+
+const payments = [...firstPaymentById.values()];
+const eligiblePayments = payments.filter((p) => p.status === 'paid' && orderById.has(p.order_id));
+const paidByOrder = new Map(orders.map((o) => [o.order_id, 0]));
+for (const p of eligiblePayments) paidByOrder.set(p.order_id, paidByOrder.get(p.order_id) + p.amount);
+
+const corrections = new Map([['R303', 'settled']]);
+const refundRows = readCsv('refunds.csv').map((r) => ({ ...r, amount: Number(r.amount) }));
+const effectiveRefunds = [];
+const orphanRefunds = [];
+for (const refund of refundRows) {
+  const status = corrections.get(refund.refund_id) ?? refund.status;
+  const payment = firstPaymentById.get(refund.payment_id);
+  if (status === 'settled' && payment && eligiblePayments.some((p) => p.payment_id === payment.payment_id) && payment.order_id === refund.order_id) {
+    effectiveRefunds.push(refund);
+  } else if (status === 'settled' && (!payment || !eligiblePayments.some((p) => p.payment_id === payment.payment_id) || payment.order_id !== refund.order_id)) {
+    orphanRefunds.push(refund.refund_id);
+  }
+}
+
+const appliedRefund = effectiveRefunds.reduce((sum, r) => sum + r.amount, 0);
+const totalPaid = eligiblePayments.reduce((sum, p) => sum + p.amount, 0);
+const netReceived = totalPaid - appliedRefund;
+const unpaidBeforeRefunds = orders.reduce((sum, o) => sum + Math.max(o.amount - paidByOrder.get(o.order_id), 0), 0);
+const result = {
+  refund_ids: effectiveRefunds.map((r) => r.refund_id),
+  applied_refund: appliedRefund,
+  net_received: netReceived,
+  unpaid_before_refunds: unpaidBeforeRefunds,
+  evidence: [
+    'orders.csv: O101–O106; 按 rules.md 第1条统计唯一订单，订单总额700元。',
+    'payments.csv: P201、P202、P203、P204 为匹配订单的 paid 付款；P202 重复行按 payment_id 去重。P205 孤立，P206 failed，P207 cancelled；依据 rules.md 第2–4条。',
+    'refunds.csv: R301、R302 为 settled 且匹配有效付款/订单；R304 的 P999 无法匹配，为孤立退款。依据 rules.md 第5–6条。',
+    'rules.md 第7条：未收款按每单 max(订单金额−有效付款,0) 计算，退款不增加该数值。',
+    'CORRECTION-ORCHID（用户消息 event/sequence 4）：“R303 已经人工核实为 settled”；据此覆盖 refunds.csv 中 R303 的 pending 状态并计入。'
+  ]
+};
+
+if (JSON.stringify(duplicatePaymentIds) !== JSON.stringify(['P202']) ||
+    JSON.stringify(result.refund_ids) !== JSON.stringify(['R301', 'R302', 'R303']) ||
+    result.applied_refund !== 60 || result.net_received !== 415 || result.unpaid_before_refunds !== 225) {
+  throw new Error(`Unexpected reconciliation result: ${JSON.stringify({ result, duplicatePaymentIds, orphanRefunds })}`);
+}
+
+console.log(JSON.stringify({
+  result,
+  audit: {
+    order_total: orders.reduce((sum, o) => sum + o.amount, 0),
+    valid_payment_ids: eligiblePayments.map((p) => p.payment_id),
+    total_valid_payments: totalPaid,
+    duplicate_payment_ids: duplicatePaymentIds,
+    orphan_paid_payment_ids: payments.filter((p) => p.status === 'paid' && !orderById.has(p.order_id)).map((p) => p.payment_id),
+    failed_or_cancelled_payment_ids: payments.filter((p) => ['failed', 'cancelled'].includes(p.status)).map((p) => p.payment_id),
+    orphan_refund_ids: orphanRefunds,
+    net_received: netReceived,
+    unpaid_before_refunds: unpaidBeforeRefunds
+  },
+  output_json: JSON.stringify(result, null, 2)
+}, null, 2));
*** End Patch"}
